# =============================================================================
# main.py — FastAPI Application Entry Point
# =============================================================================
# PURPOSE:
#   Creates the FastAPI app instance, registers all routers, and
#   initialises all external service providers at startup.
#
# HOW TO RUN (from src/ directory):
#   uvicorn main:app --reload --port 5000
#
# SWAGGER UI (interactive API docs — auto-generated by FastAPI):
#   http://localhost:5000/docs
#
# STARTUP SEQUENCE:
#   1. FastAPI app is created
#   2. @app.on_event("startup") fires → factories create provider instances
#   3. Provider instances are stored in app.state so routes can access them
#   4. Routes are registered via include_router()
#
# APP STATE (accessible anywhere via request.app.state):
#   app.state.llm_client      → OpenAIProvider (text generation)
#   app.state.embed_client    → EmbeddingProvider (local embeddings)
#   app.state.vector_db       → QDrantDB (vector storage + search)
#   app.state.template_parser → TemplateParser (prompt templates)
#   app.state.nlp_controller  → NlpController (assembled with all above)
#
# TEAM NOTE (Pair B — Member 4, after Phase 3 is complete):
#   Uncomment each section below as the corresponding module is implemented.
#   Keep the startup logic here simple — all business logic stays in controllers.
# =============================================================================

from fastapi import FastAPI
from fastapi.middleware.cors import CORSMiddleware

from helpers.config import get_settings
from routes.base import base_router
from routes.data import data_router
from routes.nlp import nlp_router

# ── These imports will be uncommented once the stores are implemented (Phase 3) ──
# from stores.llm.LLMFactory import LLMFactory
# from stores.vectordb.VectorDBFactory import VectorDBFactory
# from stores.llm.template.template_parser import TemplateParser
# from controllers.NlpController import NlpController


def create_app() -> FastAPI:
    """
    Application factory — creates and configures the FastAPI instance.
    """
    settings = get_settings()

    app = FastAPI(
        title=settings.APP_NAME,
        version=settings.APP_VERSION,
        description="End-to-end RAG system: upload documents, embed them, query with LLM."
    )

    # ── CORS (allows Streamlit and browser clients to call the API) ──────────
    app.add_middleware(
        CORSMiddleware,
        allow_origins=["*"],        # restrict this in production
        allow_credentials=True,
        allow_methods=["*"],
        allow_headers=["*"],
    )

    # ── Register API routers ─────────────────────────────────────────────────
    app.include_router(base_router)
    app.include_router(data_router)
    app.include_router(nlp_router)

    # ── Startup event: initialise all providers once at launch ───────────────
    @app.on_event("startup")
    async def startup_event():
        """
        Runs once when the server starts. Creates all provider instances
        and stores them in app.state for access from any route.

        TODO (Pair B — after Phase 3 stores are done):
            # Create providers via factories
            settings = get_settings()

            llm_client = LLMFactory.create("openai", settings)
            embed_client = LLMFactory.create("local_bge", settings)
            vector_db = VectorDBFactory.create("qdrant", settings)
            template_parser = TemplateParser(language="en")

            # Assemble NlpController with all dependencies
            nlp_controller = NlpController(
                llm_client=llm_client,
                embed_client=embed_client,
                vector_db=vector_db,
                template_parser=template_parser
            )

            # Store on app.state so routes can access via request.app.state
            app.state.llm_client = llm_client
            app.state.embed_client = embed_client
            app.state.vector_db = vector_db
            app.state.template_parser = template_parser
            app.state.nlp_controller = nlp_controller
        """
        print(f"{settings.APP_NAME} v{settings.APP_VERSION} started.")
        print("Provider startup not yet wired — complete Phase 3 first.")

    @app.on_event("shutdown")
    async def shutdown_event():
        print("Server shutting down.")

    return app


# Create the app instance (uvicorn looks for this variable)
app = create_app()
